import{_ as e,o as a,c as n,ag as i}from"./chunks/framework.CxkNbRKf.js";const s="/nada-documentation/images/image236.png",o="/nada-documentation/images/image237.png",l="/nada-documentation/images/image238.png",r="/nada-documentation/images/image239.png",h="/nada-documentation/images/image240.png",d="/nada-documentation/images/image241.png",c="/nada-documentation/images/image242.png",_=JSON.parse('{"title":"Translating NADA","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/translate.md","filePath":"admin-guide/web-ui/translate.md","lastUpdated":1786379412000}'),g={name:"admin-guide/web-ui/translate.md"};function p(m,t,u,f,w,b){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="translating-nada" tabindex="-1">Translating NADA <a class="header-anchor" href="#translating-nada" aria-label="Permalink to &quot;Translating NADA&quot;">​</a></h1><p>NADA was developed using English as the &quot;base&quot; language. It can however be translated, and translations can be shared. To translate NADA, click on <strong>Translate</strong> in the <strong>Settings</strong> menu.</p><p>Translating NADA is done using a user interface as described below. The output of a translation will consist of a series of PHP files (with extension [.php]) that can be uploaded on the server where NADA is installed. Instructions on where to save these files, and on how to activate a new language, are provided below. The IHSN will make translations originating from reputable organizations available on the NADA website.</p><p>NADA can be translated into any language that uses an alphabet compatible with [encoding]? This includes languages like Arabic that require a right-to-left display of strings (note that the NADA interface will not change; only the labels will be shown in right-to-left mode).</p><p>Note also that the application allows translation from English to English. This option is used to modify the display of labels/text in the NADA interface. It allows catalog administrators to adapt the user interface to specific terms used in their organization.</p><p><img src="'+s+'" alt=""></p><h2 id="adding-or-selecting-the-new-language" tabindex="-1">Adding or selecting the new language <a class="header-anchor" href="#adding-or-selecting-the-new-language" aria-label="Permalink to &quot;Adding or selecting the new language&quot;">​</a></h2><p>@todo - add a button in the UI.</p><p>Select the language and click &quot;Edit&quot;.</p><p><img src="'+o+'" alt=""></p><h2 id="translating-content-in-the-user-interface" tabindex="-1">Translating content in the user interface <a class="header-anchor" href="#translating-content-in-the-user-interface" aria-label="Permalink to &quot;Translating content in the user interface&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>The items for which no translation is available will be displayed with a red background. Enter your translation in the box. Note that if the length of the translation is significantly longer than the text in English, the text may not display properly in the interface (when used in menus, buttons, or other locations with limited space).</p><p><img src="'+r+'" alt=""></p><p>After translating a section, make sure to Save it.</p><p><img src="'+h+'" alt=""></p><p>To translate the text in an optimized manner, it will in some cases be important to know where the translation will be used. This will ensure not only that the translation is correct in the specific context where it is used but will also allow translators to verify that the translation will fit in the allocated space where it will be used (in some cases, this space can be fixed and limited; when the translation of a string significantly exceeds the length of the English text, it may result in display issues).</p><p>The following table provides information on the NADA pages where the translation contained in different sections/files will be used:</p><hr><hr><h2 id="activating-the-translation" tabindex="-1">Activating the translation <a class="header-anchor" href="#activating-the-translation" aria-label="Permalink to &quot;Activating the translation&quot;">​</a></h2><p>The Download option in the Translate summary table allows you to download the PHP files containing the translations and share them with other NADA users.</p><p><img src="'+d+'" alt=""></p><p><img src="'+c+'" alt=""></p><p>How to use these files in my NADA?</p>',25)])])}const T=e(g,[["render",p]]);export{_ as __pageData,T as default};
